class Solution:
    def canTraverseAllPairs(self, nums: List[int]) -> bool:
        """
        We need to determine if all indices in the array are connected via a graph where
        an edge exists between i and j if gcd(nums[i], nums[j]) > 1.

        Directly checking all pairs is O(N^2) which is too slow for N up to 10^5.

        Instead, we can use Union-Find (Disjoint Set Union) with a key insight:
        Two numbers are connected if they share a common prime factor.

        Approach:
        1. If there's only one element, return True.
        2. If any element is 1, then it cannot be connected to any other number (since gcd(1, x) = 1 for x > 1). 
           So if there is more than one element and any is 1, return False.
        3. For each number, factorize it into its prime factors.
        4. For each prime factor, union the current index with the first index that had this prime factor.
           This way, all indices sharing a common prime factor get merged into one component.
        5. After processing all numbers, check if all indices belong to the same component.

        Time Complexity: O(N * sqrt(max_val)) for factorization, which is acceptable since max_val <= 10^5.
        Space Complexity: O(N + max_val) for parent array and mapping primes to first occurrence index.
        """
        n = len(nums)
        if n == 1:
            return True

        # If any number is 1 and n > 1, it can't connect to others
        if 1 in nums:
            return False

        # Union-Find setup
        parent = list(range(n))
        rank = [0] * n

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            rx, ry = find(x), find(y)
            if rx == ry:
                return
            if rank[rx] < rank[ry]:
                rx, ry = ry, rx
            elif rank[rx] == rank[ry]:
                rank[rx] += 1
            parent[ry] = rx

        # Map each prime factor to the first index that contained it
        prime_to_index = {}

        for i, num in enumerate(nums):
            # Factorize num
            temp = num
            f = 2
            while f * f <= temp:
                if temp % f == 0:
                    if f in prime_to_index:
                        union(i, prime_to_index[f])
                    else:
                        prime_to_index[f] = i
                    while temp % f == 0:
                        temp //= f
                f += 1
            if temp > 1:
                if temp in prime_to_index:
                    union(i, prime_to_index[temp])
                else:
                    prime_to_index[temp] = i

        # Check if all indices are in the same component
        root = find(0)
        for i in range(1, n):
            if find(i) != root:
                return False

        return True
